const body = $('Webhook: Record Payment').first().json.body || $('Webhook: Record Payment').first().json;

// Read directly from body
let ruleId        = (body.rule_id || '').trim();
let customerId    = (body.customer_id || '').trim();
let seriesRef     = (body.series_reference || '').trim();
let customerName  = '';
let customerEmail = '';
let customerPhone = '';
let roomName      = '';
// Hoisted so they're accessible outside the try block
let dbRatePerSession   = 0;
let dbSessionsPerCycle = 0;

// Enrich from DB lookup (always prefer DB data for customer details)
try {
  const resolved = $('DB: Resolve Rule ID').first().json;
  if (!ruleId      && resolved.rule_id)      ruleId      = resolved.rule_id;
  if (!customerId  && resolved.customer_id)  customerId  = resolved.customer_id;
  if (!seriesRef   && resolved.series_reference) seriesRef = resolved.series_reference;
  customerName  = resolved.customer_name  || '';
  customerEmail = resolved.customer_email || '';
  customerPhone = resolved.customer_phone || '';
  roomName      = resolved.room_name      || '';
  dbRatePerSession   = parseFloat(resolved.rate_per_session   || '0') || 0;
  dbSessionsPerCycle = parseInt(resolved.sessions_per_cycle   || '0') || 0;
} catch(e) { /* lookup not available — continue */ }

const tenantId    = parseInt(body.tenant_id || '1001');
const amountPaid  = parseFloat(body.amount_paid || '0') || 0;
const method      = (body.payment_method || 'cash').toLowerCase();
const plan        = (body.payment_plan || 'per_session').toLowerCase();
const performedBy = (body.performed_by || 'Staff').trim();
const scheduleId  = (body.payment_schedule_id || body.schedule_id || '').trim();

if (!ruleId && !scheduleId) throw new Error('rule_id or payment_schedule_id is required');
if (!tenantId)              throw new Error('tenant_id is required');

const validPlans = ['in_advance','per_session','in_arrears','per_period'];
const safePlan = validPlans.includes(plan) ? plan : 'per_session';

// Session-level distribution fields (use body values, fall back to DB-resolved values)
const sessionPrice    = parseFloat(body.session_price || '0') || dbRatePerSession || 0;
const sessionsPerCyc  = parseInt(body.sessions_per_cycle || '0') || dbSessionsPerCycle || 4;
const sessionsToPay   = (sessionPrice > 0 && amountPaid > 0)
  ? Math.floor(amountPaid / sessionPrice)
  : 0;

return [{ json: {
  rule_id:             ruleId,
  tenant_id:           tenantId,
  amount_paid:         amountPaid,
  payment_method:      method,
  payment_plan:        safePlan,
  performed_by:        performedBy,
  customer_id:         customerId,
  customer_name:       customerName,
  customer_email:      customerEmail,
  customer_phone:      customerPhone,
  room_name:           roomName,
  series_reference:    seriesRef,
  payment_schedule_id: scheduleId,
  has_payment:         amountPaid > 0,
  apply_to_sessions:   !!(body.apply_to_sessions),
  session_price:       sessionPrice,
  sessions_per_cycle:  sessionsPerCyc,
  sessions_to_pay:     sessionsToPay
} }];

