// Pass-through: resolve happens inside POST /recurring/record-series-payment.
// Expose webhook body fields so Code: Validate & Prepare can read them.
const wh = $('Webhook: Record Payment').first().json;
const body = wh.body || wh;
return [{ json: {
  rule_id:          body.rule_id || '',
  series_id:        body.rule_id || '',
  recurring_rule_id:body.rule_id || '',
  customer_id:      body.customer_id || '',
  series_reference: body.series_reference || '',
  customer_name:    body.customer_name   || '',
  customer_email:   body.customer_email  || '',
  customer_phone:   body.customer_phone  || '',
  room_name:        body.room_name       || '',
  rate_per_session: body.session_price   || 0,
  sessions_per_cycle: body.sessions_per_cycle || 4,
  is_new_series:    true,
} }];
